function bh_intent_data($title){
  $rows=[
    ['درب جلو|درب بالا',['ماشین لباسشویی','ماشین لباسشویی'], '<h2>درب جلو یا درب بالا؛ تفاوت واقعی در استفاده روزمره</h2><p>مدل درب جلو معمولاً برای چیدمان زیر کابینت و مصرف بهینه‌تر آب مناسب است و امکان قرار دادن لباس بیشتر در یک چرخه را فراهم می‌کند؛ درب بالا برای بعضی خانه‌ها دسترسی ساده‌تر و افزودن لباس در میانه برنامه را راحت‌تر می‌کند. فضای باز شدن درب، ارتفاع کاربر، برنامه‌های موردنیاز و دسترسی به خدمات را کنار هم بسنجید.</p><div class="bh-article-compare"><div><strong>درب جلو</strong><span>مصرف کمتر آب، چیدمان زیرکار، خشک‌کن قوی‌تر</span></div><div><strong>درب بالا</strong><span>دسترسی ساده‌تر، اشغال فضای کمتر در جلو</span></div></div>'],
    ['ظرفیت.*لباسشویی|لباسشویی.*ظرفیت',['ماشین لباسشویی'], '<h2>ظرفیت روی کاغذ با ظرفیت قابل استفاده فرق دارد</h2><p>ظرفیت اسمی لباسشویی با وزن خشک لباس محاسبه می‌شود، اما در عمل حجم پتو، جنس پارچه، فضای گردش آب و کیفیت آبکشی تعیین‌کننده است. برای تصمیم بهتر، الگوی شست‌وشوی خانه را ثبت کنید و دستگاه را همیشه فشرده پر نکنید؛ یک‌چهارم فضای دیگ باید برای حرکت لباس‌ها خالی بماند.</p>'],
    ['ظرفیت.*سرخ|سرخ.*ظرفیت',['سرخ‌کن بدون روغن'], '<h2>ظرفیت سرخ‌کن را با تعداد نفرات و نوع غذا بسنجید</h2><p>ظرفیت اسمی همیشه به معنی فضای قابل استفاده برای پخت یکنواخت نیست. اگر غذا را روی هم فشرده کنید، گردش هوای گرم کم می‌شود و نتیجه ضعیف خواهد بود. برای خانواده‌های پرجمعیت یا پخت هم‌زمان، سبد بزرگ‌تر یا مدل دوقلو را با فضای روی کابینت مقایسه کنید.</p>'],
    ['ظرفیت واقعی لوازم خانگی',['راهنمای خرید'], '<h2>ظرفیت واقعی با ظرفیت تبلیغاتی یکی نیست</h2><p>ظرفیت اسمی معمولاً با شرایط استاندارد سازنده اعلام می‌شود، اما در عمل نوع مواد، حجم ظرف، فضای گردش هوا و امکان پخت یا شست‌وشوی یکنواخت تعیین‌کننده است. برای تصمیم بهتر، یک هفته الگوی مصرف خانه را ثبت کنید و ظرفیت را کمی بالاتر از نیاز معمول انتخاب کنید؛ پر کردن فشرده دستگاه نتیجه را ضعیف می‌کند.</p>'],
    ['فیلتر جاروبرقی|صدای جاروبرقی|کیسه‌ای یا مخزن‌دار',['جاروبرقی و نظافت','جاروبرقی و نظافت','جاروبرقی و نظافت'], '<h2>قبل از خرید جاروبرقی این سه آزمایش را انجام دهید</h2><ol><li>سطح صدا را در فاصله معمول نشستن و کنار دستگاه بررسی کنید.</li><li>قیمت و دسترسی کیسه، فیلتر و برس یدکی را بپرسید.</li><li>وزن، طول سیم، شعاع کارکرد و راحتی حرکت روی فرش را امتحان کنید.</li></ol><p>عدد توان موتور به تنهایی معیار مکش نیست؛ طراحی مسیر هوا، آب‌بندی و برس کف را هم در نظر بگیرید.</p>'],
    ['رزولوشن|فاصله‌های مختلف|فیلم و بازی|اتاق روشن',['صوتی و تصویری','صوتی و تصویری','صوتی و تصویری','صوتی و تصویری'], '<h2>تلویزیون را با شرایط اتاق خود بسنجید</h2><p>برای اتاق روشن، کنترل بازتاب و روشنایی واقعی مهم‌تر از عدد کنتراست روی بروشور است. برای بازی، تأخیر ورودی، نرخ نوسازی و پورت مناسب اهمیت دارد. برای فیلم، عمق مشکی و یکنواختی تصویر را بررسی کنید. اندازه صفحه را نیز با فاصله نشستن و زاویه دید هماهنگ کنید.</p>'],
    ['گارانتی|خدمات پس از فروش|مرجوعی',['خرید مطمئن و خدمات','خرید مطمئن و خدمات','خرید مطمئن و خدمات'], '<h2>گارانتی خوب چه ویژگی‌هایی دارد؟</h2><p>فقط نام شرکت کافی نیست. مدت پوشش، قطعات تحت ضمانت، هزینه ایاب‌وذهاب، شرایط ابطال گارانتی، زمان پاسخ‌گویی و شبکه خدمات را بررسی کنید. هنگام تحویل، مدل، سریال و سلامت ظاهری را ثبت کنید و فاکتور و شرایط مرجوعی را نگه دارید.</p>'],
    ['مصرف انرژی|کاهش مصرف انرژی',['مصرف انرژی','مصرف انرژی'], '<h2>مصرف سالانه را به هزینه واقعی تبدیل کنید</h2><p>برای مقایسه، فقط رتبه انرژی را نبینید؛ مصرف سالانه، تعداد دفعات استفاده و تعرفه برق خانه را هم کنار هم قرار دهید. دستگاهی که کمی گران‌تر است اگر در چند سال مصرف کمتری داشته باشد، ممکن است هزینه مالکیت پایین‌تری ایجاد کند. تمیز نگه داشتن فیلتر، لاستیک و مسیر تهویه نیز مصرف را کاهش می‌دهد.</p>'],
    ['چای‌ساز|کتری برقی',['چای‌ساز و کتری برقی','چای‌ساز و کتری برقی'], '<h2>آب سخت و رسوب را از روز اول مدیریت کنید</h2><p>رسوب علاوه بر تغییر طعم آب، زمان جوش آمدن و فشار روی المنت را بیشتر می‌کند. مقدار آب موردنیاز را بجوشانید، آب باقی‌مانده را طولانی داخل کتری نگه ندارید و رسوب‌زدایی را فقط با روش سازنده انجام دهید. بدنه و پایه را نیز از نفوذ آب دور نگه دارید.</p>'],
    ['مایکروویو|سولاردام',['مایکروویو و سولاردام','مایکروویو و سولاردام'], '<h2>ایمنی ظرف و برنامه پخت را جدی بگیرید</h2><p>ظرف فلزی، ظروف ترک‌دار یا درب کاملاً بسته می‌توانند خطر ایجاد کنند. برای یخ‌زدایی، گرم کردن و پخت ترکیبی از برنامه مناسب استفاده کنید و غذا را در میانه کار هم بزنید تا گرما یکنواخت‌تر پخش شود. پس از هر استفاده، دیواره و لاستیک درب را پاک کنید.</p>'],
    ['یخچال|فریزر',['یخچال و فریزر','یخچال و فریزر'], '<h2>سه نشانه که می‌گوید چیدمان یا تنظیمات درست نیست</h2><ul><li>مواد نزدیک دیواره پشتی یخ می‌زنند.</li><li>کمپرسور مدت طولانی بدون توقف کار می‌کند.</li><li>بوی نامطبوع با وجود سرمای کافی باقی می‌ماند.</li></ul><p>در این شرایط ابتدا مسیر هوا، آب‌بندی درب، دمای تنظیم‌شده و نظافت کندانسور را بررسی کنید؛ اگر مشکل ادامه داشت، سراغ تعمیرکار مجاز بروید.</p>'],
  ];
  foreach($rows as [$pattern,$categories,$html]) if(preg_match('/'.$pattern.'/u',$title)) return [$categories[0],$html];
  $fallbacks=[
    'لباسشویی'=>'ماشین لباسشویی','یخچال|فریزر'=>'یخچال و فریزر','جاروبرقی'=>'جاروبرقی و نظافت','سرخ‌کن|سرخکن'=>'سرخ‌کن بدون روغن','ظرفشویی'=>'ماشین ظرفشویی','اسپرسوساز'=>'اسپرسوساز','قهوه‌ساز|قهوه ساز|کپسول‌ساز'=>'چای‌ساز و کتری برقی','چای‌ساز|کتری'=>'چای‌ساز و کتری برقی','مایکروویو|سولاردام'=>'مایکروویو و سولاردام','غذاساز|خردکن|مخلوط‌کن|همزن|ساندویچ'=>'لوازم آماده‌سازی غذا','تلویزیون|رزولوشن'=>'صوتی و تصویری','اتو'=>'اتو و بخار','کولر|تهویه|تصفیه هوا|پنکه'=>'تهویه','هود'=>'اجاق و فر','انرژی'=>'راهنمای خرید','گارانتی|خدمات|مرجوعی'=>'خرید مطمئن و خدمات'
  ];
  foreach($fallbacks as $pattern=>$category) if(preg_match('/'.$pattern.'/u',$title)) return [$category,$title];
  return ['راهنمای خرید',$title];
}
$posts=get_posts(['post_type'=>'post','post_status'=>'publish','posts_per_page'=>-1,'orderby'=>'ID','order'=>'ASC']);$n=0;
foreach($posts as $post){
  if(trim($post->post_title)==='سلام دنیا!')continue;
  [$category,$block]=bh_intent_data($post->post_title);
  $term=term_exists($category,'category'); if(!$term)$term=wp_insert_term($category,'category');
  $cat_id=is_array($term)?(int)$term['term_id']:(int)$term;
  wp_set_post_categories($post->ID,[$cat_id],false);
  if(!get_post_meta($post->ID,'_bh_intent_review_v2',true)){
    $content=$post->post_content;
    $marker='<h2>پرسش‌های متداول</h2>';
    $content=strpos($content,$marker)!==false?str_replace($marker,$block.$marker,$content):$content.$block;
    wp_update_post(['ID'=>$post->ID,'post_content'=>$content]);
    update_post_meta($post->ID,'_bh_intent_review_v2','completed');$n++;
  }
  echo "audited={$post->ID} category={$category}\n";
}
echo "intent_updated={$n}\n";
